function combatBarsV29(a){return `<span class="combat-bars-v29"><span class="hp"><i style="width:${hpPct(a)}%"></i></span><span class="mp"><i style="width:${mpPct(a)}%"></i></span><small>HP ${Math.max(0,Math.round(a.hp))} / MP ${Math.round(a.mp)}</small></span>`;}
function allyStageV29(a,superSub=false){return `<button type="button" class="ally-field-unit-v5 ${superSub?'super-unit-v29':''} ${battle.activeActor===a?'active':''} ${a.hp<=0?'dead':''}" data-combat-uid="${a.uid}" data-ally-inspect="${a.uid}" ${battle.targetSide==='ally'&&battle.targetResolve&&a.hp>0?`data-battle-target="${a.uid}"`:''}><b class="ally-name-v29">${esc(a.name)}</b>${battleArtMarkup(a.m,'ally-field-art-v5')}${superSub?combatBarsV29(a):''}</button>`;}
