 $$('[data-battle-enemy]').forEach(el=>el.onclick=()=>{if(!battle||battle.targetResolve)return;const e=activeEnemies().find(x=>x.uid===el.dataset.battleEnemy);if(!e)return;battle.selectedEnemyUid=e.uid;$$('[data-battle-enemy]').forEach(b=>{const chosen=b.dataset.battleEnemy===e.uid;b.classList.toggle('selected-target',chosen);b.setAttribute('aria-pressed',String(chosen));});$('.target-info-v29').innerHTML=`<b>${esc(e.name)}</b><span>${esc(e.m.species)} / ${esc(e.m.attribute)}</span>`;});
 $$('[data-ally-inspect]').forEach(el=>el.onclick=()=>{if(!battle.targetResolve&&!battle.choiceLock)inspectAllyV29(el.dataset.allyInspect);});bindBattleTargetsV3();if(actor?.side==='ally'&&battle.choiceResolve&&!battle.choiceLock)bindCommands(actor);
